package com.gb.astralita.world;
import com.gb.astralita.AstralitaMod;import com.gb.astralita.registry.ModBlocks;import net.minecraft.core.registries.Registries;import net.minecraft.data.worldgen.features.OreFeatures;import net.minecraft.world.level.levelgen.VerticalAnchor;import net.minecraft.world.level.levelgen.feature.*;import net.minecraft.world.level.levelgen.feature.configurations.OreConfiguration;import net.minecraft.world.level.levelgen.placement.*;import net.minecraftforge.eventbus.api.IEventBus;import net.minecraftforge.registries.*;import java.util.List;
public class ModWorldgen{public static final DeferredRegister<ConfiguredFeature<?,?>> CONFIGURED=DeferredRegister.create(Registries.CONFIGURED_FEATURE,AstralitaMod.MODID);public static final DeferredRegister<PlacedFeature> PLACED=DeferredRegister.create(Registries.PLACED_FEATURE,AstralitaMod.MODID);public static final RegistryObject<ConfiguredFeature<?,?>> ORE=CONFIGURED.register("astralita_ore",()->new ConfiguredFeature<>(Feature.ORE,new OreConfiguration(List.of(OreConfiguration.target(OreFeatures.END_STONE_REPLACEABLES,ModBlocks.MINERIO_ASTRALITA.get().defaultBlockState())),3,.25F)));public static final RegistryObject<PlacedFeature> ORE_PLACED=PLACED.register("astralita_ore",()->new PlacedFeature(ORE.getHolder().get(),List.of(CountPlacement.of(2),InSquarePlacement.spread(),HeightRangePlacement.uniform(VerticalAnchor.absolute(0),VerticalAnchor.absolute(80)),BiomeFilter.biome())));public static void register(IEventBus b){CONFIGURED.register(b);PLACED.register(b);}}
